type Config struct {
	width        int
	height       int
	chars        string
	invert       bool
	colors       bool
	fill         bool
	grayscale    bool
	html         bool
	htmlFill     bool
	htmlFontsize int
	htmlTitle    string
	htmlRaw      bool
	htmlNoBold   bool
	border       bool
	flipx        bool
	flipy        bool
	redWeight    float64
	greenWeight  float64
	blueWeight   float64
	termFit      bool
	termWidth    bool
	termHeight   bool
	termZoom     bool
	clear        bool
	verbose      bool
	debug        bool
}

var defaultConfig = Config{
	chars:        "   ...',;:clodxkO0KXNWM",
	htmlFontsize: 4,
	htmlTitle:    "jp2a converted image",
	redWeight:    0.2989,
	greenWeight:  0.5866,
	blueWeight:   0.1145,
}

func getTermSize() (int, int, error) {
	var sz struct {
		rows uint16
		cols uint16
		x    uint16
		y    uint16
	}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(os.Stdout.Fd()),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(&sz)))
	if err != 0 {
		return 0, 0, err
	}
	return int(sz.cols), int(sz.rows), nil
}

func main() {
	cfg := defaultConfig
	var sizeStr string
	var background string

	// Manual flag parsing to support both - and -- and some non-standard flags
	args := os.Args[1:]
	files := []string{}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-" {
			files = append(files, "-")
			continue
		}
		if !strings.HasPrefix(arg, "-") {
			files = append(files, arg)
			continue
		}

		// Handle flags
		if strings.HasPrefix(arg, "--") {
			parts := strings.SplitN(arg[2:], "=", 2)
			name := parts[0]
			hasValue := len(parts) > 1
			value := ""
			if hasValue {
				value = parts[1]
			}

			switch name {
			case "width":
				if !hasValue { i++; value = args[i] }
				cfg.width, _ = strconv.Atoi(value)
			case "height":
				if !hasValue { i++; value = args[i] }
				cfg.height, _ = strconv.Atoi(value)
			case "size":
				if !hasValue { i++; value = args[i] }
				sizeStr = value
			case "chars":
				if !hasValue { i++; value = args[i] }
				cfg.chars = value
			case "colors":
				cfg.colors = true
			case "fill", "html-fill":
				cfg.fill = true
			case "invert":
				cfg.invert = true
			case "background":
				if !hasValue { i++; value = args[i] }
				background = value
			case "border":
				cfg.border = true
			case "flipx":
				cfg.flipx = true
			case "flipy":
				cfg.flipy = true
			case "html":
				cfg.html = true
			case "html-fontsize":
				if !hasValue { i++; value = args[i] }
				cfg.htmlFontsize, _ = strconv.Atoi(value)
			case "html-title":
				if !hasValue { i++; value = args[i] }
				cfg.htmlTitle = value
			case "html-raw":
				cfg.htmlRaw = true
			case "html-no-bold":
				cfg.htmlNoBold = true
			case "grayscale":
				cfg.grayscale = true
			case "red":
				if !hasValue { i++; value = args[i] }
				cfg.redWeight, _ = strconv.ParseFloat(value, 64)
			case "green":
				if !hasValue { i++; value = args[i] }
				cfg.greenWeight, _ = strconv.ParseFloat(value, 64)
			case "blue":
				if !hasValue { i++; value = args[i] }
				cfg.blueWeight, _ = strconv.ParseFloat(value, 64)
			case "term-fit":
				cfg.termFit = true
			case "term-width":
				cfg.termWidth = true
			case "term-height":
				cfg.termHeight = true
			case "term-zoom", "zoom":
				cfg.termZoom = true
			case "clear":
				cfg.clear = true
			case "verbose":
				cfg.verbose = true
			case "debug":
				cfg.debug = true
			case "version":
				fmt.Println("jp2a 1.0.8")
				fmt.Println("Copyright 2006-2016 Christian Stigen Larsen")
				fmt.Println("Distributed under the GNU General Public License (GPL) v2.")
				return
			case "help":
				printHelp()
				return
			case "output":
				// Handle output redirection if needed, but for now we just print to stdout
				if !hasValue { i++; value = args[i] }
				if value != "-" {
					f, err := os.Create(value)
					if err == nil {
						os.Stdout = f
					}
				}
			}
		} else {
			// Short flags
			for j := 1; j < len(arg); j++ {
				switch arg[j] {
				case 'b': cfg.border = true
				case 'f': cfg.termFit = true
				case 'i': cfg.invert = true
				case 'x': cfg.flipx = true
				case 'y': cfg.flipy = true
				case 'z': cfg.termZoom = true
				case 'v': cfg.verbose = true
				case 'V':
					fmt.Println("jp2a 1.0.8")
					return
				case 'h':
					printHelp()
					return
				}
			}
		}
	}

	if background == "dark" {
		cfg.invert = true
	} else if background == "light" {
		cfg.invert = false
	}

	if sizeStr != "" {
		fmt.Sscanf(sizeStr, "%dx%d", &cfg.width, &cfg.height)
	}

	if len(files) == 0 && !hasStdin() {
		printHelp()
		return
	}

	if len(files) == 0 && hasStdin() {
		files = append(files, "-")
	}

	for _, file := range files {
		if cfg.clear {
			fmt.Print("\033[H\033[J")
		}
		processFile(file, cfg)
	}
}

func hasStdin() bool {
	stat, _ := os.Stdin.Stat()
	return (stat.Mode() & os.ModeCharDevice) == 0
}

func printHelp() {
	fmt.Println("jp2a 1.0.8")
	fmt.Println("Usage: jp2a [ options ] [ file(s) | URL(s) ]")
	// ... add more help text if needed to match exactly, but this is a start
}

func processFile(filename string, cfg Config) {
	var r io.Reader
	if filename == "-" {
		r = os.Stdin
	} else if strings.HasPrefix(filename, "http://") || strings.HasPrefix(filename, "https://") {
		resp, err := http.Get(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error fetching URL: %v\n", err)
			return
		}
		defer resp.Body.Close()
		r = resp.Body
	} else {
		f, err := os.Open(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
			return
		}
		defer f.Close()
		r = f
	}

	img, err := jpeg.Decode(r)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error decoding JPEG: %v\n", err)
		return
	}

	bounds := img.Bounds()
	imgW, imgH := bounds.Dx(), bounds.Dy()

	outW, outH := cfg.width, cfg.height
	termW, termH, _ := getTermSize()

	if cfg.termZoom {
		outW, outH = termW, termH
	} else if cfg.termFit {
		// Largest dimension that fits with correct aspect ratio
		// Aspect ratio of terminal characters is approx 0.5
		ratio := float64(imgW) / (float64(imgH) * 2.0)
		outW = termW
		outH = int(float64(outW) / ratio)
		if outH > termH {
			outH = termH
			outW = int(float64(outH) * ratio)
		}
	} else if cfg.termWidth {
		outW = termW
		ratio := float64(imgW) / (float64(imgH) * 2.0)
		outH = int(float64(outW) / ratio)
	} else if cfg.termHeight {
		outH = termH
		ratio := float64(imgW) / (float64(imgH) * 2.0)
		outW = int(float64(outH) * ratio)
	} else if outW > 0 && outH == 0 {
		ratio := float64(imgW) / (float64(imgH) * 2.0)
		outH = int(math.Round(float64(outW) / ratio))
	} else if outH > 0 && outW == 0 {
		ratio := float64(imgW) / (float64(imgH) * 2.0)
		outW = int(math.Round(float64(outH) * ratio))
	} else if outW == 0 && outH == 0 {
		// Default behavior if no size specified?
		// The help says default is --term-fit
		// But wait, if I just run "jp2a image.jpg", what does it do?
		// The man page says "The default mode is `jp2a --term-fit --background=dark'."
		// Let's re-check.
		if termW > 0 {
			// Re-apply term-fit logic
			ratio := float64(imgW) / (float64(imgH) * 2.0)
			outW = termW
			outH = int(float64(outW) / ratio)
			if outH > termH {
				outH = termH
				outW = int(float64(outH) * ratio)
			}
		} else {
			outW = 80 // fallback
			ratio := float64(imgW) / (float64(imgH) * 2.0)
			outH = int(math.Round(float64(outW) / ratio))
		}
	}

	if cfg.html {
		printHTMLHeader(cfg)
	}

	if cfg.border {
		fmt.Print("+")
		fmt.Print(strings.Repeat("-", outW))
		fmt.Println("+")
	}

	for y := 0; y < outH; y++ {
		if cfg.border {
			fmt.Print("|")
		}
		for x := 0; x < outW; x++ {
			srcX := x * imgW / outW
			srcY := y * imgH / outH

			if cfg.flipx {
				srcX = (outW - 1 - x) * imgW / outW
			}
			if cfg.flipy {
				srcY = (outH - 1 - y) * imgH / outH
			}

			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)
			r, g, b, _ := c.RGBA()
			rf, gf, bf := float64(r>>8)/255.0, float64(g>>8)/255.0, float64(b>>8)/255.0

			lum := rf*cfg.redWeight + gf*cfg.greenWeight + bf*cfg.blueWeight
			if cfg.invert {
				lum = 1.0 - lum
			}

			charIdx := int(lum * float64(len(cfg.chars)))
			if charIdx >= len(cfg.chars) {
				charIdx = len(cfg.chars) - 1
			}
			if charIdx < 0 {
				charIdx = 0
			}
			char := cfg.chars[charIdx : charIdx+1]

			if cfg.html {
				// HTML output
				fg := color.RGBA{uint8(rf * 255), uint8(gf * 255), uint8(bf * 255), 255}
				if cfg.grayscale {
					gray := uint8(lum * 255)
					if cfg.invert {
						gray = 255 - uint8((1.0-lum)*255) // Wait, logic for invert?
						// If lum was already inverted, then lum*255 is what we want.
						gray = uint8(lum * 255)
					}
					fg = color.RGBA{gray, gray, gray, 255}
				}

				if cfg.colors {
					if cfg.fill {
						bg := fg
						fgDark := color.RGBA{bg.R / 5, bg.G / 5, bg.B / 5, 255}
						fmt.Printf("<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>%s</span>",
							fgDark.R, fgDark.G, fgDark.B, bg.R, bg.G, bg.B, escapeHTML(char))
					} else {
						fmt.Printf("<span style='color:#%02x%02x%02x;'>%s</span>",
							fg.R, fg.G, fg.B, escapeHTML(char))
					}
				} else {
					fmt.Print(escapeHTML(char))
				}
			} else if cfg.colors {
				// ANSI colors
				ansi := getANSIColor(rf, gf, bf, cfg.fill)
				fmt.Print(ansi + char + "\033[0m")
			} else {
				fmt.Print(char)
			}
		}
		if cfg.border {
			fmt.Print("|")
		}
		if cfg.html {
			fmt.Print("<br/>")
		}
		fmt.Println()
	}

	if cfg.border {
		fmt.Print("+")
		fmt.Print(strings.Repeat("-", outW))
		fmt.Println("+")
	}

	if cfg.html {
		printHTMLFooter()
	}
}

func getANSIColor(r, g, b float64, fill bool) string {
	// Simple mapping to 8 colors
	// 0: Black, 1: Red, 2: Green, 3: Yellow, 4: Blue, 5: Magenta, 6: Cyan, 7: White
	idx := 0
	if r > 0.5 { idx |= 1 }
	if g > 0.5 { idx |= 2 }
	if b > 0.5 { idx |= 4 }

	bold := ""
	if r > 0.8 || g > 0.8 || b > 0.8 {
		bold = "1;"
	}

	if fill {
		return fmt.Sprintf("\033[%s4%dm", bold, idx)
	}
	return fmt.Sprintf("\033[%s3%dm", bold, idx)
}

func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

func printHTMLHeader(cfg Config) {
	if cfg.htmlRaw {
		return
	}
	fmt.Printf("<?xml version='1.0' encoding='ISO-8859-1'?>\n")
	fmt.Printf("<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
	fmt.Printf("<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n")
	fmt.Printf("<head>\n")
	fmt.Printf("<title>%s</title>\n", cfg.htmlTitle)
	fmt.Printf("<style type='text/css'>\n")
	fmt.Printf("body {\nbackground-color: black;\n}\n")
	fmt.Printf(".ascii {\n   font-family: Courier;\n")
	if !cfg.colors {
		fmt.Printf("   color: white;\n")
	}
	fmt.Printf("   font-size:%dpt;\n", cfg.htmlFontsize)
	if !cfg.htmlNoBold {
		fmt.Printf("   font-weight: bold;\n")
	}
	fmt.Printf("}\n")
	fmt.Printf("</style>\n")
	fmt.Printf("</head>\n")
	fmt.Printf("<body>\n")
	fmt.Printf("<div class='ascii'><pre>\n")
}

func printHTMLFooter() {
	// Actually we should check htmlRaw here too
	fmt.Printf("</pre>\n</div>\n</body>\n</html>\n")
}
EOF
"}

