func processFile(filename string, cfg Config, out io.Writer) {
	var r io.Reader
	if filename == "-" {
		r = os.Stdin
	} else if strings.HasPrefix(filename, "http://") || strings.HasPrefix(filename, "https://") {
		resp, err := http.Get(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return
		}
		defer resp.Body.Close()
		r = resp.Body
	} else {
		f, err := os.Open(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return
		}
		defer f.Close()
		r = f
	}

	img, err := jpeg.Decode(r)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return
	}

	bounds := img.Bounds()
	imgW, imgH := bounds.Dx(), bounds.Dy()

	termW, termH, _ := getTermSize()
	if termW == 0 { termW = 80 }
	if termH == 0 { termH = 25 }

	outW, outH := cfg.width, cfg.height

	if cfg.termZoom {
		outW, outH = termW, termH
	} else if cfg.termFit {
		outW = termW
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
		if outH > termH {
			outH = termH
			outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
		}
	} else if cfg.termWidth {
		outW = termW
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
	} else if cfg.termHeight {
		outH = termH
		outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
	} else if outW > 0 && outH == 0 {
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
	} else if outH > 0 && outW == 0 {
		outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
	} else if outW == 0 && outH == 0 {
		// Default is term-fit
		outW = termW
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
		if outH > termH {
			outH = termH
			outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
		}
	}

	if cfg.html {
		printHTMLHeader(cfg, out)
	}

	if cfg.border {
		fmt.Fprint(out, "+")
		fmt.Fprint(out, strings.Repeat("-", outW))
		fmt.Fprintln(out, "+")
	}

	for y := 0; y < outH; y++ {
		if cfg.border {
			fmt.Fprint(out, "|")
		}
		for x := 0; x < outW; x++ {
			ix, iy := x, y
			if cfg.flipx { ix = outW - 1 - x }
			if cfg.flipy { iy = outH - 1 - y }

			srcX := ix * imgW / outW
			srcY := iy * imgH / outH

			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)
			r, g, b, _ := c.RGBA()
			ru, gu, bu := uint8(r>>8), uint8(g>>8), uint8(b>>8)
			rf, gf, bf := float64(ru)/255.0, float64(gu)/255.0, float64(bu)/255.0

			lum := rf*cfg.redWeight + gf*cfg.greenWeight + bf*cfg.blueWeight

			effectiveLum := lum
			if cfg.invert {
				effectiveLum = 1.0 - lum
			}

			charIdx := int(effectiveLum * float64(len(cfg.chars)))
			if charIdx >= len(cfg.chars) { charIdx = len(cfg.chars) - 1 }
			if charIdx < 0 { charIdx = 0 }
			char := cfg.chars[charIdx : charIdx+1]

			if cfg.html {
				fgR, fgG, fgB := ru, gu, bu
				if cfg.grayscale {
					y := uint8(lum * 255.0)
					fgR, fgG, fgB = y, y, y
				}
				if cfg.colors {
					if cfg.fill {
						fmt.Printf("<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>%s</span>",
							fgR/5, fgG/5, fgB/5, fgR, fgG, fgB, escapeHTML(char))
					} else {
						fmt.Printf("<span style='color:#%02x%02x%02x;'>%s</span>",
							fgR, fgG, fgB, escapeHTML(char))
					}
				} else {
					fmt.Fprint(out, escapeHTML(char))
				}
			} else if cfg.colors {
				ansi := getANSIColor(ru, gu, bu, cfg.fill)
				fmt.Fprint(out, ansi + char + "\033[0m")
			} else {
				fmt.Fprint(out, char)
			}
		}
		if cfg.border {
			fmt.Fprint(out, "|")
		}
		if cfg.html {
			fmt.Fprint(out, "<br/>")
		}
		fmt.Fprintln(out)
	}

	if cfg.border {
		fmt.Fprint(out, "+")
		fmt.Fprint(out, strings.Repeat("-", outW))
		fmt.Fprintln(out, "+")
	}

	if cfg.html {
		printHTMLFooter(cfg, out)
	}
}

func getANSIColor(r, g, b uint8, fill bool) string {
	idx := 0
	if r > 127 { idx |= 1 }
	if g > 127 { idx |= 2 }
	if b > 127 { idx |= 4 }

	bold := ""
	if r > 200 || g > 200 || b > 200 {
		bold = "1;"
	}

	code := 30 + idx
	if fill { code = 40 + idx }
	return fmt.Sprintf("\033[%s%dm", bold, code)
}

func escapeHTML(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;").Replace(s)
}

func printHTMLHeader(cfg Config, out io.Writer) {
	if cfg.htmlRaw { return }
	fmt.Fprintf(out, "<?xml version='1.0' encoding='ISO-8859-1'?>\n")
	fmt.Fprintf(out, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
	fmt.Fprintf(out, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n")
	fmt.Fprintf(out, "<head>\n<title>%s</title>\n<style type='text/css'>\n", cfg.htmlTitle)
	fmt.Fprintf(out, "body {\nbackground-color: black;\n}\n.ascii {\n   font-family: Courier;\n")
	if !cfg.colors { fmt.Fprintf(out, "   color: white;\n") }
	fmt.Fprintf(out, "   font-size:%dpt;\n", cfg.htmlFontsize)
	if !cfg.htmlNoBold { fmt.Fprintf(out, "   font-weight: bold;\n") }
	fmt.Fprintf(out, "}\n</style>\n</head>\n<body>\n<div class='ascii'><pre>\n")
}

func printHTMLFooter(cfg Config, out io.Writer) {
	if cfg.htmlRaw { return }
	fmt.Fprintf(out, "</pre>\n</div>\n</body>\n</html>\n")
}
