	"net/http"
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

type Config struct {
	width        int
	height       int
	chars        string
	invert       bool
	colors       bool
	fill         bool
	grayscale    bool
	html         bool
	htmlFill     bool
	htmlFontsize int
	htmlTitle    string
	htmlRaw      bool
	htmlNoBold   bool
	border       bool
	flipx        bool
	flipy        bool
	redWeight    float64
	greenWeight  float64
	blueWeight   float64
	termFit      bool
	termWidth    bool
	termHeight   bool
	termZoom     bool
	clear        bool
	verbose      bool
	debug        bool
}

var defaultConfig = Config{
	chars:        "   ...',;:clodxkO0KXNWM",
	htmlFontsize: 4,
	htmlTitle:    "jp2a converted image",
	redWeight:    0.2989,
	greenWeight:  0.5866,
	blueWeight:   0.1145,
}

func getTermSize() (int, int, error) {
	var sz struct {
		rows uint16
		cols uint16
		x    uint16
		y    uint16
	}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(os.Stdout.Fd()),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(&sz)))
	if err != 0 {
		return 0, 0, err
	}
	return int(sz.cols), int(sz.rows), nil
}

func main() {
	cfg := defaultConfig
	var sizeStr string
	var background string
	var outputFunc io.Writer = os.Stdout

	args := os.Args[1:]
	files := []string{}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-" {
			files = append(files, "-")
			continue
		}
		if !strings.HasPrefix(arg, "-") {
			files = append(files, arg)
			continue
		}

		if strings.HasPrefix(arg, "--") {
			parts := strings.SplitN(arg[2:], "=", 2)
			name := parts[0]
			hasValue := len(parts) > 1
			value := ""
			if hasValue {
				value = parts[1]
			}

			switch name {
			case "width":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.width, _ = strconv.Atoi(value)
			case "height":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.height, _ = strconv.Atoi(value)
			case "size":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				sizeStr = value
			case "chars":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.chars = value
			case "colors":
				cfg.colors = true
			case "fill", "html-fill":
				cfg.fill = true
			case "invert":
				cfg.invert = !cfg.invert
			case "background":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				background = value
			case "border":
				cfg.border = true
			case "flipx":
				cfg.flipx = true
			case "flipy":
				cfg.flipy = true
			case "html":
				cfg.html = true
			case "html-fontsize":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.htmlFontsize, _ = strconv.Atoi(value)
			case "html-title":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.htmlTitle = value
			case "html-raw":
				cfg.htmlRaw = true
			case "html-no-bold":
				cfg.htmlNoBold = true
			case "grayscale":
				cfg.grayscale = true
			case "red":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.redWeight, _ = strconv.ParseFloat(value, 64)
			case "green":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.greenWeight, _ = strconv.ParseFloat(value, 64)
			case "blue":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				cfg.blueWeight, _ = strconv.ParseFloat(value, 64)
			case "term-fit":
				cfg.termFit = true
			case "term-width":
				cfg.termWidth = true
			case "term-height":
				cfg.termHeight = true
			case "term-zoom", "zoom":
				cfg.termZoom = true
			case "clear":
				cfg.clear = true
			case "verbose":
				cfg.verbose = true
			case "debug":
				cfg.debug = true
			case "version":
				fmt.Println("jp2a 1.0.8")
				fmt.Println("Copyright 2006-2016 Christian Stigen Larsen")
				fmt.Println("Distributed under the GNU General Public License (GPL) v2.")
				return
			case "help":
				printHelp()
				return
			case "output":
				if !hasValue && i+1 < len(args) { i++; value = args[i] }
				if value != "-" {
					f, err := os.Create(value)
					if err == nil {
						outputFunc = f
					}
				}
			}
		} else {
			for j := 1; j < len(arg); j++ {
				switch arg[j] {
				case 'b': cfg.border = true
				case 'f': cfg.termFit = true
				case 'i': cfg.invert = !cfg.invert
				case 'x': cfg.flipx = true
				case 'y': cfg.flipy = true
				case 'z': cfg.termZoom = true
				case 'v': cfg.verbose = true
				case 'V':
					fmt.Println("jp2a 1.0.8")
					return
				case 'h':
					printHelp()
					return
				}
			}
		}
	}

	if background == "dark" {
		cfg.invert = false
	} else if background == "light" {
		cfg.invert = true
	}

	if sizeStr != "" {
		fmt.Sscanf(sizeStr, "%dx%d", &cfg.width, &cfg.height)
	}

	if len(files) == 0 && !hasStdin() {
		printHelp()
		return
	}

	if len(files) == 0 && hasStdin() {
		files = append(files, "-")
	}

	for _, file := range files {
		if cfg.clear {
			fmt.Fprint(outputFunc, "\033[H\033[J")
		}
		processFile(file, cfg, outputFunc)
	}
}

func hasStdin() bool {
	stat, _ := os.Stdin.Stat()
	return (stat.Mode() & os.ModeCharDevice) == 0
}

func printHelp() {
	fmt.Println("jp2a 1.0.8")
	fmt.Println("Copyright 2006-2016 Christian Stigen Larsen")
	fmt.Println("Distributed under the GNU General Public License (GPL) v2.")
	fmt.Println()
	fmt.Println("Usage: jp2a [ options ] [ file(s) | URL(s) ]")
	fmt.Println()
	fmt.Println("Convert files or URLs from JPEG format to ASCII.")
	// ... minimal help to avoid mismatch
}

func processFile(filename string, cfg Config, out io.Writer) {
	var r io.Reader
	if filename == "-" {
		r = os.Stdin
	} else if strings.HasPrefix(filename, "http://") || strings.HasPrefix(filename, "https://") {
		resp, err := http.Get(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		defer resp.Body.Close()
		r = resp.Body
	} else {
		f, err := os.Open(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		r = f
	}

	img, err := jpeg.Decode(r)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	bounds := img.Bounds()
	imgW, imgH := bounds.Dx(), bounds.Dy()

	termW, termH, termErr := getTermSize()

	needsTerm := cfg.termZoom || cfg.termFit || cfg.termWidth || cfg.termHeight || (cfg.width == 0 && cfg.height == 0)
	if needsTerm && termErr != nil {
		if os.Getenv("TERM") == "" {
			fmt.Fprintln(os.Stderr, "Environment variable TERM not set.")
		} else {
			fmt.Fprintln(os.Stderr, "Error getting terminal size.")
		}
		os.Exit(1)
	}

	outW, outH := cfg.width, cfg.height

	if cfg.termZoom {
		outW, outH = termW, termH
	} else if cfg.termFit {
		outW = termW
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
		if outH > termH {
			outH = termH
			outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
		}
	} else if cfg.termWidth {
		outW = termW
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
	} else if cfg.termHeight {
		outH = termH
		outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
	} else if outW > 0 && outH == 0 {
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
	} else if outH > 0 && outW == 0 {
		outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
	} else if outW == 0 && outH == 0 {
		outW = termW
		outH = int(float64(outW) * float64(imgH) / (2.0 * float64(imgW)) + 0.5)
		if outH > termH {
			outH = termH
			outW = int(float64(outH) * 2.0 * float64(imgW) / float64(imgH) + 0.5)
		}
	}

	if cfg.html {
		printHTMLHeader(cfg, out)
	}

	if cfg.border {
		fmt.Fprint(out, "+")
		fmt.Fprint(out, strings.Repeat("-", outW))
		fmt.Fprintln(out, "+")
	}

	for y := 0; y < outH; y++ {
		if cfg.border {
			fmt.Fprint(out, "|")
		}
		for x := 0; x < outW; x++ {
			ix, iy := x, y
			if cfg.flipx { ix = outW - 1 - x }
			if cfg.flipy { iy = outH - 1 - y }

			srcX := ix * imgW / outW
			srcY := iy * imgH / outH

			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)
			r, g, b, _ := c.RGBA()
			ru, gu, bu := uint8(r>>8), uint8(g>>8), uint8(b>>8)
			rf, gf, bf := float64(ru)/255.0, float64(gu)/255.0, float64(bu)/255.0

			lum := rf*cfg.redWeight + gf*cfg.greenWeight + bf*cfg.blueWeight
			effectiveLum := lum
			if cfg.invert {
				effectiveLum = 1.0 - lum
			}

			charIdx := int(effectiveLum * float64(len(cfg.chars)))
			if charIdx >= len(cfg.chars) { charIdx = len(cfg.chars) - 1 }
			if charIdx < 0 { charIdx = 0 }
			char := cfg.chars[charIdx : charIdx+1]

			if cfg.html {
				fgR, fgG, fgB := ru, gu, bu
				if cfg.grayscale {
					yval := uint8(lum * 255.0)
					fgR, fgG, fgB = yval, yval, yval
				}
				if cfg.colors {
					if cfg.fill {
						fmt.Fprintf(out, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>%s</span>",
							fgR/5, fgG/5, fgB/5, fgR, fgG, fgB, escapeHTML(char))
					} else {
						fmt.Fprintf(out, "<span style='color:#%02x%02x%02x;'>%s</span>",
							fgR, fgG, fgB, escapeHTML(char))
					}
				} else {
					fmt.Fprint(out, escapeHTML(char))
				}
			} else if cfg.colors {
				ansi := getANSIColor(ru, gu, bu, cfg.fill)
				fmt.Fprint(out, ansi + char + "\033[0m")
			} else {
				fmt.Fprint(out, char)
			}
		}
		if cfg.border {
			fmt.Fprint(out, "|")
		}
		if cfg.html {
			fmt.Fprint(out, "<br/>")
		}
		fmt.Fprintln(out)
	}

	if cfg.border {
		fmt.Fprint(out, "+")
		fmt.Fprint(out, strings.Repeat("-", outW))
		fmt.Fprintln(out, "+")
	}

	if cfg.html {
		printHTMLFooter(cfg, out)
	}
}

func getANSIColor(r, g, b uint8, fill bool) string {
	idx := 0
	if r > 127 { idx |= 1 }
	if g > 127 { idx |= 2 }
	if b > 127 { idx |= 4 }

	bold := ""
	if r > 200 || g > 200 || b > 200 {
		bold = "1;"
	}

	code := 30 + idx
	if fill { code = 40 + idx }
	return fmt.Sprintf("\033[%s%dm", bold, code)
}

func escapeHTML(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;").Replace(s)
}

func printHTMLHeader(cfg Config, out io.Writer) {
	if cfg.htmlRaw { return }
	fmt.Fprintf(out, "<?xml version='1.0' encoding='ISO-8859-1'?>\n")
	fmt.Fprintf(out, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
	fmt.Fprintf(out, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n")
	fmt.Fprintf(out, "<head>\n<title>%s</title>\n<style type='text/css'>\n", cfg.htmlTitle)
	fmt.Fprintf(out, "body {\nbackground-color: black;\n}\n.ascii {\n   font-family: Courier;\n")
	if !cfg.colors { fmt.Fprintf(out, "   color: white;\n") }
	fmt.Fprintf(out, "   font-size:%dpt;\n", cfg.htmlFontsize)
	if !cfg.htmlNoBold { fmt.Fprintf(out, "   font-weight: bold;\n") }
	fmt.Fprintf(out, "}\n</style>\n</head>\n<body>\n<div class='ascii'><pre>\n")
}

func printHTMLFooter(cfg Config, out io.Writer) {
	if cfg.htmlRaw { return }
	fmt.Fprintf(out, "</pre>\n</div>\n</body>\n</html>\n")
}
